import{_ as o,o as r,c as t,a2 as a}from"./chunks/framework.BDCokyix.js";const b=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"01-glossary.md","filePath":"01-glossary.md","lastUpdated":1780254295000}'),s={name:"01-glossary.md"};function n(i,e,p,d,c,l){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p><strong>Space</strong><br> A shared collaboration unit containing documents, members, and resources.</p><p><strong>Workspace</strong><br> Product-level term for a private collaboration group; currently modeled by spaces and their associated content, members, and permissions.</p><p><strong>Topic</strong><br> A node in the space tree. Can contain content and sub-topics.</p><p><strong>Document</strong><br> The editable content attached to a topic.</p><p><strong>Page</strong><br> The main navigable note or document unit inside a workspace.</p><p><strong>Blob</strong><br> An attachment (PDF, image, etc.), content-addressed by hash.</p><p><strong>Daemon</strong><br> The local backend handling networking, storage, and permissions. On desktop, it runs in-process inside the Tauri <code>src-tauri</code> host (via the <code>desktop-daemon</code> crate) — no separate process.</p><p><strong>soma-daemon</strong><br> The desktop peer/daemon library crate (libp2p peer + storage). Embedded by the Tauri host (<code>desktop-daemon</code>); no standalone binary.</p><p><strong>soma-agentd</strong><br> The desktop agent library crate (Yjs drift resolver and helpers). Embedded by the Tauri host (<code>desktop-agent</code>); no standalone binary.</p><p><strong>somad</strong><br> The unified server binary. Subcommands <code>bot</code>, <code>relay</code>, <code>rendezvous</code>, <code>bff</code>, and <code>all</code> (TOML-composed multi-mode) replace the former per-service binaries.</p><ul><li><code>somad bot</code>: server peer/bot (libp2p peer + Axum control plane + metrics).</li><li><code>somad relay</code>: libp2p Circuit Relay + Axum + metrics.</li><li><code>somad rendezvous</code>: libp2p Rendezvous discovery + Axum + metrics.</li><li><code>somad bff</code>: LLM BFF (Axum + metrics; no libp2p).</li></ul><p><strong>PeerId</strong><br> Cryptographic identity of a device.</p><p><strong>Capability</strong><br> A signed token granting permissions in a space.</p><p><strong>Model Feature Hint</strong><br> Local desktop metadata describing whether an AI model is suitable for chat, embedding, tool use, or image work. These hints do not grant any space permissions.</p><p><strong>MembershipCapability</strong><br> Grants a peer access to a space.</p><p><strong>Role</strong><br> The human-facing access level inside a space, such as Owner, Editor, Viewer, Member, or Bot.</p><p><strong>IssuerCapability</strong><br> Delegates authority from an owner to a bot or trusted member.</p><p><strong>Bot</strong><br> A non-human space member that can cache content, serve content, organize resources, or run approved automation depending on its granted capabilities.</p><p><strong>Delegated Approver</strong><br> A peer that has been explicitly delegated authority to approve memberships for a space. A delegated approver may be a bot, but bot membership alone does not grant this authority.</p><p><strong>Relay</strong><br> A connectivity service that forwards encrypted traffic.</p><p><strong>Rendezvous</strong><br> A discovery service helping peers find each other.</p><p><strong>Mailbox</strong><br> A bot-backed queue for delivering approvals asynchronously.</p><p><strong>Tapia</strong><br> Typing-practice surface (short passages, generated drills, and session feedback) planned to live at the <code>/practice</code> route inside the Soma desktop app. The <code>/practice</code> route is not yet wired in the Tauri app; the migration is a tracked follow-up.</p><p><strong>Soma</strong><br> The main structured note-taking and workspace application in the platform.</p>',25)])])}const m=o(s,[["render",n]]);export{b as __pageData,m as default};
